import{_ as a,o as t,c as n,a3 as o}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"1.2 What Are the Benefits of Blocking Control?","description":"","frontmatter":{"translationSource":{"title":"1.2 采用阻塞控制有什么好处","archivedAt":"2026-11-14","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=vjw47WlrDGyaYlemKyfnH8","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/1-2-what-are-the-benefits-of-blocking-based-production"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/1-2-what-are-the-benefits-of-blocking-based-production"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/1-2-what-are-the-benefits-of-blocking-based-production"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/1-2-what-are-the-benefits-of-blocking-based-production"}]]},"headers":[],"relativePath":"1-2-what-are-the-benefits-of-blocking-based-production.md","filePath":"logistics/src/page-vjw47WlrDGyaYlemKyfnH8.md"}'),s={name:"1-2-what-are-the-benefits-of-blocking-based-production.md"};function r(i,e,l,p,c,u){return t(),n("div",null,[...e[0]||(e[0]=[o('<div class="logistics-content"><h1 id="_1-2-what-are-the-benefits-of-blocking-control" tabindex="-1">1.2 What Are the Benefits of Blocking Control? <a class="header-anchor" href="#_1-2-what-are-the-benefits-of-blocking-control" aria-label="Permalink to &quot;1\\.2 What Are the Benefits of Blocking Control?&quot;">​</a></h1><blockquote><p>Source page ID: <code>vjw47WlrDGyaYlemKyfnH8</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=vjw47WlrDGyaYlemKyfnH8" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Compared with conventional fixed-rate production, a well-designed blocking-control scheme can make advanced production requirements much easier to meet. For example:</p><ol><li><p><span class="mark-purple">I want to produce </span><span class="mark-purple"><u>a depot full of Amethyst Bottles</u></span><span class="mark-purple"> before beginning </span><span class="mark-purple"><u>Cryston Bottles</u></span><span class="mark-purple">.</span></p></li><li><p><span class="mark-purple">I want </span><span class="mark-purple"><u>Steel Parts always available in the depot</u></span><span class="mark-purple"> without wasting Steel capacity while they are unused: everything goes to Valley Batteries instead.</span></p></li><li><p><span class="mark-purple">I want Cuprium to </span><span class="mark-purple"><u>make Cuprium Parts first</u></span><span class="mark-purple">. To prevent full Cuprium storage blocking Sewage, once parts fill up, </span><span class="mark-purple"><u>Cuprium should continue making Cuprium Components</u></span><span class="mark-purple">.</span></p></li><li><p><span class="mark-purple">I want Xiranite to </span><span class="mark-purple"><u>satisfy SC Wuling Battery production first</u></span><span class="mark-purple">, using the remainder elsewhere, so even occasional extra Originium Powder brought from the Valley is consumed.</span></p></li><li><p><span class="mark-purple">I want to </span><span class="mark-purple"><u>turn every input into finished products</u></span><span class="mark-purple">. Even complicated fractional production rates can be reached automatically through adaptation.</span></p></li><li><p><span class="mark-purple">I do not want transmuters freeloading on Xiranite: supply it according to available inputs.</span></p></li></ol><p>Meeting these common advanced production requirements with conventional direct production often requires manual adjustments, such as changing machine recipes. Besides being inconvenient, forgetting to act or being unable to log in at the right time can waste materials or even cause a power outage. Blocking control uses a specific production-line design to switch production plans automatically, achieving these goals without intervention and reducing the work we need to do.</p><p><a href="/endfield-skydoc/1-1-so-tell-me-what-is-production-controlled-by-blocking">1.1 So Tell Me, What Is Blocking Control?</a></p><p><a href="/endfield-skydoc/1-3-glossary">1.3 Glossary (Even I Cannot Fully Define These; You Can Skip It)</a></p></div>',1)])])}const m=a(s,[["render",r]]);export{h as __pageData,m as default};
